/* Untrusted on-device model output is an intent suggestion, never an executable command. */
(()=>{
 'use strict';
 const intents=Object.freeze(['favorites','cabinet','my_bids','purchases','map','feed','catalog','sell','search','help','unsupported']);
 const routes=Object.freeze({favorites:['Открыть избранное','Открой избранное'],cabinet:['Открыть кабинет','Открой личный кабинет'],my_bids:['Открыть мои ставки','Открой мои ставки'],purchases:['Открыть покупки','Открой мои покупки'],map:['Открыть карту','Открой карту'],feed:['Открыть ленту','Открой ленту'],catalog:['Открыть каталог','Открой каталог']});
 const answers=Object.freeze({
  help:{title:'Проверенные правила и справка',text:'Сейчас это демоверсия: реальные платежи, банковское обеспечение и общие серверные счета не подключены. После первой принятой ставки предмет, продавца и опубликованные условия менять нельзя; снятие до установленного окончания блокируется. Уточнения, фото и документы не должны подменять объект. Цену и статус проверяйте в карточке, а вопросы собственности, законности, документов и денег — с человеком: Fastorgy@gmail.com. Профиль и черновики хранятся в выбранном браузере. Помощник не подтверждает оплату, право собственности или победу.',source:'Пользовательское соглашение, разделы 2, 4, 5, 7, 8 и 10; Политика конфиденциальности'},
  help_auction:{title:'Правила торгов',text:'После первой принятой ставки нельзя заменять предмет и продавца, менять стартовую цену и опубликованные условия или снимать лот до установленного окончания. Допускаются уточнения, фото и документы без подмены объекта. Условия конкретного лота проверяйте в его карточке.',source:'Пользовательское соглашение, раздел 5'},
  help_payments:{title:'Ставки и оплата',text:'Сейчас это демоверсия. Реальные платежи, банковское обеспечение и общие серверные счета не подключены. Демоставки и демопокупка не подтверждают оплату или резерв денег. Не переводите деньги по демонстрационным образцам. Текущую цену и статус проверяйте в карточке лота.',source:'Пользовательское соглашение, разделы 2 и 7'},
  help_legal:{title:'Юридические вопросы',text:'Соглашение определяет обязанности сторон и не отменяет обязательную ответственность по закону. Вопросы о собственности, обременениях, спорных документах, блокировках и денежных требованиях требуют проверки человеком. Обращения: Fastorgy@gmail.com. Помощник не подтверждает законность сделки.',source:'Пользовательское соглашение, разделы 4, 8 и 10'},
  help_privacy:{title:'Данные и конфиденциальность',text:'Профиль, черновики и демодействия сейчас хранятся в выбранном браузере. Очистка данных или другое устройство могут сделать их недоступными. В локальную модель передаётся только написанный здесь запрос, без профиля, документов и истории торгов. Не вводите паспортные данные, пароли и платёжные секреты.',source:'Политика конфиденциальности и инструкция локальной модели'},
  help_notifications:{title:'Оповещения помощника',text:'В настройках помощника можно отдельно включить шесть событий, озвучивание и тихие часы. Оповещения работают на открытой странице и относятся к выбранному профилю. Закрытая страница не обеспечивает постоянное наблюдение за торгами.',source:'Пособие: настройки и оповещения помощника'},
  sell:{title:'Размещение имущества',text:'Нажмите «Продать» в основном меню, заполните сведения о конкретном предмете, местонахождении и условиях. Право продажи и документы проверяются отдельно. Помощник не публикует объявление автоматически.',source:'Пособие: размещение лота'},
  unsupported:{title:'Нужно уточнение',text:'Локальная модель не смогла надёжно выбрать действие. Напишите конкретнее, например «открой избранное» или «найди красный пикап». Для вопросов о деньгах и документах используйте правила сайта и поддержку.',source:'Справка помощника'}
 });
 function parse(raw){
  if(typeof raw!=='string'||raw.length>200)return null;
  let value;try{value=JSON.parse(raw)}catch{return null}
  if(!value||Array.isArray(value)||typeof value!=='object'||Object.keys(value).length!==1||!Object.hasOwn(value,'intent')||!intents.includes(value.intent))return null;
  return Object.freeze({intent:value.intent});
 }
 function proposal(raw,query){
  const parsed=parse(raw),intent=parsed?.intent||'unsupported';
  if(routes[intent])return Object.freeze({intent,kind:'route',title:routes[intent][0],command:routes[intent][1],text:'Модель предлагает действие. Проверьте его перед открытием.',source:'Навигация сайта'});
  if(intent==='search'&&typeof query==='string'&&query.trim().length>0&&query.trim().length<=450)return Object.freeze({intent,kind:'search',title:'Искать по этому запросу',command:/^(?:(?:пожалуйста|please)[, ]+)?(?:хочу (?:найти|купить)|найди|найти|поищи|покажи|показать|ищи|ищу|мне нужен|мне нужна|мне нужно|search|find|show)(?:\s|[:：])/i.test(query.trim())?query.trim():'Найди '+query.trim(),text:query.trim(),source:'Поиск сайта; критерии проверяются штатным поиском'});
  const answer=answers[intent]||answers.unsupported;return Object.freeze({intent,kind:'help',...answer});
 }

 const api=Object.freeze({intents,routes,answers,parse,proposal});
 if(typeof module!=='undefined'&&module.exports)module.exports=api;
 else globalThis.FasLocalAIPolicy=api;
})();
